const api=async<T=any>(path:string,opts?:RequestInit):Promise<T>=>{const r=await fetch(path,{...opts,headers:{'Content-Type':'application/json',...(opts?.headers||{})}});const body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(body.error||`HTTP ${r.status}`);return body}
const fmt=(v?:string)=>v?new Date(v).toLocaleString('de-DE'):'—'
const fmtBytes=(v?:number)=>{const n=Number(v||0);if(!Number.isFinite(n)||n<=0)return '0 B';const u=['B','KiB','MiB','GiB','TiB','PiB'];let x=n,i=0;while(x>=1024&&i<u.length-1){x/=1024;i++}return `${x>=100||i===0?x.toFixed(0):x>=10?x.toFixed(1):x.toFixed(2)} ${u[i]}`}
const fmtPct=(v?:number)=>Number.isFinite(Number(v))?`${Number(v||0).toFixed(1)}%`:'—'
const storageTotal=(s?:HostStorage)=>Number(s?.restore_total_bytes||s?.host_total_bytes||0)
const storageFree=(s?:HostStorage)=>Number(s?.restore_free_bytes||s?.host_free_bytes||0)
const memorySourceLabel=(v?:string)=>v==='docker-info'?'Docker info':v==='docker-stats-limit'?'Docker stats':v==='unavailable'?'Unavailable':v||''
const hostAddress=(endpoint?:string)=>{const v=String(endpoint||'');if(v.startsWith('unix://'))return 'Local socket';const m=v.match(/^(?:tcp|tls):\/\/([^:/]+|\[[^\]]+\]):\d+$/);return m?m[1].replace(/^\[|\]$/g,''):v||'—'}
const hostConnectionType=(h:Host)=>h.connection_type||(h.endpoint.startsWith('tls://')?'tls':h.endpoint.startsWith('unix://')?'local':'tcp')
const hostConnectionLabel=(h:Host)=>hostConnectionType(h)==='tls'?'Secure':hostConnectionType(h)==='local'?'Local':'TCP'
const certificateDaysRemaining=(v?:string)=>{const t=v?new Date(v).getTime():0;if(!t||Number.isNaN(t))return null;return Math.max(0,Math.ceil((t-Date.now())/86400000))}
const shortDigest=(v?:string)=>{const raw=String(v||'').trim();if(!raw)return '';const body=raw.startsWith('sha256:')?raw.slice(7):raw;return `${raw.startsWith('sha256:')?'sha256:':''}${body.slice(0,12)}${body.length>12?'…':''}`}
const sameDigest=(a?:string,b?:string)=>!!String(a||'').trim()&&String(a||'').trim().toLowerCase()===String(b||'').trim().toLowerCase()
const notificationFingerprint=(...parts:any[])=>{const raw=parts.map(v=>typeof v==='string'?v:JSON.stringify(v??null)).join('\u001f');let hash=2166136261;for(let i=0;i<raw.length;i++){hash^=raw.charCodeAt(i);hash=Math.imul(hash,16777619)}return(hash>>>0).toString(16).padStart(8,'0')}
const dependencyTone=(s?:string)=>s==='success'?'green':s==='failed'||s==='snapshot_failed'?'red':s==='not_required'?'blue':s&&s!=='none'?'yellow':'gray'
const verificationTone=(s?:string)=>s==='verified'?'green':s==='failed'?'red':s==='pending'||s==='running'?'blue':'gray'
const verificationLabel=(s?:string)=>s==='verified'?'Verified':s==='failed'?'Failed':s==='pending'?'Not yet verified':s==='running'?'Running':'Not configured'
const preflightTone=(s?:string)=>s==='ready'?'green':s==='ready_with_warnings'?'yellow':s==='blocked'?'red':'gray'
const preflightLabel=(s?:string)=>s==='ready'?'Ready':s==='ready_with_warnings'?'Ready with warnings':s==='blocked'?'Blocked':'Not run'
const preflightLiveStages=[
 {key:'prepare',label:'Prepare',detail:'Load the Docker host and initialize the safety review'},
 {key:'inspect',label:'Container inspection',detail:'Inspect runtime state and network namespace dependencies'},
 {key:'verify',label:'Verification posture',detail:'Review Docker health and custom verification coverage'},
 {key:'registry',label:'Image & registry',detail:'Resolve manifest, architecture and update metadata'},
 {key:'recovery',label:'Recovery readiness',detail:'Check storage, mounts, data protection and rollback configuration'},
 {key:'complete',label:'Decision',detail:'Summarize warnings and blocking conditions'},
] as const
function preflightLiveStageKey(stage?:string){const s=String(stage||'').toLowerCase();if(/blocked|ready|complete/.test(s))return'complete';if(/volume|bind|restore|snapshot|storage/.test(s))return'recovery';if(/registry|manifest|architecture/.test(s))return'registry';if(/health|verification/.test(s))return'verify';if(/inspect|dependenc|container/.test(s))return'inspect';return'prepare'}
function preflightCheckStageKey(key?:string){const k=String(key||'').toLowerCase();if(k==='host')return'prepare';if(['dependencies','container_state'].includes(k))return'inspect';if(['docker_health','custom_verification'].includes(k))return'verify';if(['registry','architecture','new_image','major_version'].includes(k))return'registry';if(['volumes','bind_mounts','data_protection','restore_storage','restore_configuration','config_snapshot','dependency_snapshots','restore_point','transaction_state','automatic_safety'].includes(k))return'recovery';return'recovery'}
const policyModeLabel=(m?:string)=>m==='auto'?'Auto Update':m==='ignore'?'Excluded':'Manual'
const prettyToken=(v?:string)=>String(v||'').replace(/[_-]+/g,' ').replace(/\b\w/g,m=>m.toUpperCase())
const historyDetailTone=(status?:string)=>{const s=String(status||'').toLowerCase();return s==='green'||s==='verified'||s==='success'||s==='passed'?'green':s==='red'||s==='failed'||s==='blocked'?'red':s==='yellow'||s==='warning'||s==='pending'||s==='not_run'?'yellow':s==='info'||s==='running'?'blue':'gray'}
const historyDetailStatus=(status?:string)=>{const s=String(status||'').toLowerCase();return s==='green'?'Passed':s==='red'?'Blocked':s==='yellow'?'Warning':s==='info'?'Info':s==='verified'?'Verified':s==='not_run'?'Not run':s==='not_configured'?'Not configured':s?prettyToken(s):'Info'}
function parseHistoryDetail(raw:string,kind:'preflight'|'verification'){
 const text=String(raw||'').trim();if(!text)return [] as any[]
 let data:any;try{data=JSON.parse(text)}catch{return[{title:kind==='preflight'?'Preflight detail':'Verification detail',status:'info',detail:text}]}
 const source=Array.isArray(data)?data:Array.isArray(data?.checks)?data.checks:[data]
 return source.filter(Boolean).map((x:any,index:number)=>{
  if(kind==='preflight')return{title:String(x.title||prettyToken(x.key)||`Check ${index+1}`),status:String(x.status||'info'),detail:[x.description,x.detail,x.error].filter(Boolean).join(' · '),meta:[x.source,x.duration_ms?`${x.duration_ms} ms`:null].filter(Boolean).join(' · ')}
  const target=String(x.target||x.url||x.host||'').trim(),type=String(x.type||'verification').toUpperCase();return{title:x.type?`${type} check`:prettyToken(x.type||'Verification'),status:String(x.status||data?.status||'info'),detail:[target,x.http_status?`HTTP ${x.http_status}`:null,x.attempts?`${x.attempts} attempt${Number(x.attempts)===1?'':'s'}`:null,x.error,x.detail].filter(Boolean).join(' · '),meta:x.duration_ms?`${x.duration_ms} ms`:''}
 })
}
function HistoryDetailBlock({raw,kind}:{raw:string,kind:'preflight'|'verification'}){const rows=parseHistoryDetail(raw,kind);if(!rows.length)return null;return <div className="v2-history-detail-wide"><span>{kind==='preflight'?'Preflight detail':'Verification detail'}</span><div className="v2-history-detail-list">{rows.map((row:any,index:number)=><div key={`${row.title}-${index}`} className="v2-history-detail-item"><Badge tone={historyDetailTone(row.status)}>{historyDetailStatus(row.status)}</Badge><span><b>{row.title}</b>{row.detail?<small>{row.detail}</small>:null}{row.meta?<em>{row.meta}</em>:null}</span></div>)}</div></div>}
const isSnoozedUpdate=(c:Container)=>{const s=String(c.update?.snoozed_digest||'').trim(),latest=String(c.update?.latest_digest||'').trim();if(!s)return false;if(!latest)return !!c.update?.snoozed_at;return sameDigest(s,latest)&&!sameDigest(c.update?.current_digest,latest)}
const imageStatus=(c:Container)=>{if(c.system_managed)return{key:'system',label:'Managed in Settings',tone:'gray',detail:'Owner maintenance'};if(c.update?.last_error)return{key:'unavailable',label:'Check unavailable',tone:'red',detail:c.update.last_error};if(isSnoozedUpdate(c))return c.rollback_snoozed?{key:'snoozed',label:'Rolled back · Snoozed',tone:'yellow',detail:'The failed update digest is snoozed until a newer image appears'}:{key:'snoozed',label:'Update snoozed',tone:'yellow',detail:'This digest is skipped until a newer image appears'};if(c.update?.update_available){const installed=String(c.version?.installed_version||'').trim(),latest=String(c.version?.latest_version||'').trim();if(installed&&latest)return{key:'update',label:'Update available',tone:'blue',detail:installed===latest?'Same version label · image digest changed':'Image digest changed'};return{key:'update',label:'Update available',tone:'blue',detail:'Digest changed · version metadata incomplete'}}if(c.update?.last_checked_at)return{key:'current',label:'Up to date',tone:'green',detail:'Image digest matches'};return{key:'unchecked',label:'Not checked',tone:'gray',detail:'No digest comparison yet'}}
const updateKindLabel=(c:Container)=>{const k=String(c.version?.update_kind||'').toLowerCase();if(k==='major')return 'Major';if(k==='minor')return 'Minor';if(k==='patch')return 'Patch';if(k==='image')return 'Digest';return c.update?.update_available?'Digest':''}
const effectiveContainerPolicyMode=(c:Container)=>String(c.chain_management?.policy_mode||c.policy?.mode||'manual').toLowerCase()
const isExcludedContainer=(c:Container)=>effectiveContainerPolicyMode(c)==='ignore'
const updateKindTone=(c:Container)=>c.version?.security_update?'red':c.version?.update_kind==='major'?'yellow':c.version?.update_kind==='minor'?'blue':c.version?.update_kind==='patch'?'green':'gray'
const updateClassification=(c:Container)=>({kind:updateKindLabel(c),security:!!c.version?.security_update})
const jobTransactionTypeLabel=(j?:Job)=>{const t=String(j?.type||'').toLowerCase();if(t==='update')return 'Container update';if(t==='rollback')return 'Rollback';if(t==='chain')return 'Update chain';if(t==='check')return 'Update check';if(t.includes('cleanup'))return 'Cleanup';return j?.type||'Transaction'}
const jobTransactionTypeTone=(j?:Job)=>{const t=String(j?.type||'').toLowerCase();return t==='rollback'?'yellow':t==='chain'?'blue':t==='update'?'green':'gray'}
type TransactionStepState='done'|'failed'|'active'|'pending'|'blocked'
type TransactionFlowStep={label:string,detail:string,icon:string,state:TransactionStepState}
const latestProgressStage=(logs:JobLog[])=>{for(let i=logs.length-1;i>=0;i--){const l=logs[i];if(String(l.source||'').toLowerCase()!=='progress')continue;return String(l.message||'').replace(/^\s*\d+\s*\|\s*/,'').trim()}return''}
const transactionFlowForJob=(job?:Job,logs:JobLog[]=[])=>{
 const kind=String(job?.type||'').toLowerCase(),stage=latestProgressStage(logs),signal=`${stage} ${job?.error||''}`.toLowerCase()
 const steps:TransactionFlowStep[]=kind==='rollback'?[{label:'Restore point',detail:'Recovery source',icon:'archive',state:'pending'},{label:'Safety snapshot',detail:'Before rollback',icon:'shield',state:'pending'},{label:'Restore',detail:'Previous state',icon:'rollback',state:'pending'},{label:'Verification',detail:'Application',icon:'check',state:'pending'}]:kind==='chain'?[{label:'Preflight',detail:'Safety gate',icon:'shield',state:'pending'},{label:'Restore points',detail:'Recovery',icon:'archive',state:'pending'},{label:'Update chain',detail:'Deploy',icon:'chains',state:'pending'},{label:'Verification',detail:'Services',icon:'check',state:'pending'}]:[{label:'Preflight',detail:'Safety gate',icon:'shield',state:'pending'},{label:'Restore point',detail:'Recovery',icon:'archive',state:'pending'},{label:'Update',detail:'Deploy',icon:'download',state:'pending'},{label:'Verification',detail:'Application',icon:'check',state:'pending'}]
 if(!job)return{steps,stage:'',failure:''}
 if(job.status==='success'){steps.forEach(x=>x.state='done');return{steps,stage:stage||'Completed',failure:''}}
 if(kind==='rollback'){
  if(job.status==='running'){
   if(/verif/.test(signal)){steps[0].state=steps[1].state=steps[2].state='done';steps[3].state='active'}
   else if(/restor/.test(signal)){steps[0].state=steps[1].state='done';steps[2].state='active'}
   else if(/safety snapshot/.test(signal)){steps[0].state='done';steps[1].state='active'}
   else steps[0].state='active'
  }else if(job.status==='failed'){
   if(/verif/.test(signal)){steps[0].state=steps[1].state=steps[2].state='done';steps[3].state='failed'}
   else if(/snapshot/.test(signal)){steps[0].state='done';steps[1].state='failed'}
   else{steps[0].state='done';steps[1].state='done';steps[2].state='failed'}
  }
 }else{
  const preflightFailed=/preflight|manifest unavailable|architecture not verified/.test(signal)&&job.status==='failed'
  const verificationStage=/verification|docker health|health check/.test(signal)
  const restoreFailure=/restore point|snapshot/.test(signal)&&job.status==='failed'&&!preflightFailed
  if(job.status==='running'){
   if(verificationStage){steps[0].state=steps[1].state=steps[2].state='done';steps[3].state='active'}
   else if(/update engine|preparing update worker|deploy|step \d+\//.test(signal)){steps[0].state=steps[1].state='done';steps[2].state='active'}
   else if(/preflight/.test(signal)){steps[0].state='active'}
   else steps[0].state='active'
  }else if(job.status==='failed'){
   if(preflightFailed){steps[0].state='failed';steps.slice(1).forEach(x=>x.state='blocked')}
   else if(restoreFailure){steps[0].state='done';steps[1].state='failed';steps.slice(2).forEach(x=>x.state='blocked')}
   else if(verificationStage){steps[0].state=steps[1].state=steps[2].state='done';steps[3].state='failed'}
   else{steps[0].state=steps[1].state='done';steps[2].state='failed';steps[3].state='blocked'}
  }else if(job.status==='skipped'){steps[0].state='blocked';steps.slice(1).forEach(x=>x.state='blocked')}
 }
 return{steps,stage,failure:job.status==='failed'?job.error||stage:''}
}
