const verificationDrawerLabel=(v?:VerificationState)=>v?.scope_type==='stack'?`Stack · ${verificationLabel(v?.status)}`:`Verification · ${verificationLabel(v?.status)}`
const configTableLabel=(s?:string)=>s==='drift'?'Config: Drift':s==='matches'?'Config: OK':s==='unavailable'?'Config: Check failed':'Config: No baseline'
const humanCron=(cron:string)=>{const p=String(cron||'').trim().split(/\s+/);if(p.length!==5)return cron||'Invalid schedule';const[min,hour,dom,mon,dow]=p;const hh=String(Number(hour)).padStart(2,'0');const mm=String(Number(min)).padStart(2,'0');if(/^\d+$/.test(min)&&/^\d+$/.test(hour)&&dom==='*'&&mon==='*'&&dow==='*')return `Daily at ${hh}:${mm}`;if(/^\d+$/.test(min)&&/^\d+$/.test(hour)&&dom==='*'&&mon==='*'&&/^[0-6]$/.test(dow)){const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];return `${days[Number(dow)]} at ${hh}:${mm}`}return cron}
