  if(!open)return
  const position=()=>{const rect=trigger.current?.getBoundingClientRect();if(!rect)return;const viewportPadding=12,menuWidth=Math.min(270,Math.max(180,window.innerWidth-viewportPadding*2)),menuHeight=menu.current?.offsetHeight||166;let top=rect.bottom+7;if(top+menuHeight>window.innerHeight-viewportPadding&&rect.top-menuHeight-7>=viewportPadding)top=rect.top-menuHeight-7;let left=rect.right-menuWidth;left=Math.max(viewportPadding,Math.min(left,window.innerWidth-menuWidth-viewportPadding));setMenuPos({top,left})}
