 const loadHosts=async()=>{const x=await api<Host[]>('/api/hosts');setHosts(x);const ids=new Set(x.map(h=>h.id));setByHost(v=>Object.fromEntries(Object.entries(v).filter(([id])=>ids.has(Number(id)))) as Record<number,Container[]>);setHostContainerStatus(v=>Object.fromEntries(Object.entries(v).filter(([id])=>ids.has(Number(id)))) as Record<number,HostRefreshState>);void Promise.allSettled(x.map(h=>loadContainersForHost(h,!hostContainerLastSuccess.current.has(h.id))))}
