  const overviewTask=api<HostOverview>(`/api/hosts/${h.id}/overview`).then(data=>{setHostOverview(v=>({...v,[h.id]:data}));setHostRefresh(v=>({...v,[h.id]:{...(v[h.id]||{}),loading:true,last_success:new Date().toISOString(),duration_ms:Date.now()-started,error:undefined}}))}).catch((e:any)=>{setHostRefresh(v=>({...v,[h.id]:{...(v[h.id]||{}),loading:v[h.id]?.loading??true,error:e.message||'Host overview unavailable'}}));setHostOverview(v=>v[h.id]?v:{...v,[h.id]:{error:e.message} as HostOverview})})
