 const monitorCleanup=async(h:Host,kind:'images'|'volumes'|'networks'|'build-cache',jobID:number)=>{if(cleanupMonitorInFlight.current.has(jobID))return;cleanupMonitorInFlight.current.add(jobID);const key=cleanupKey(h,kind);for(let i=0;i<3600;i++){try{const x:any=await api(`/api/job-status/${jobID}`),job:Job=x.job,progress=x.progress||{},op:CleanupOperation={job_id:jobID,status:job.status,percent:Number(progress.percent||0),stage:String(progress.stage||''),error:job.error||''};setCleanupOps(v=>({...v,[key]:op}));if(['success','failed','cancelled'].includes(job.status)){if(job.status==='success'){let result:any={};try{result=job.summary_json?JSON.parse(job.summary_json):{}}catch{};if(kind==='images')notify(`Image cleanup complete · ${result.removed_images||0} removed${Number(result.failed_images||0)?` · ${result.failed_images} failed`:''} · ${result.protected_images||0} rollback-protected · ${fmtBytes(Number(result.reclaimed_bytes||0))} reclaimed`);else if(kind==='volumes')notify(`Volume cleanup complete · ${(result.removed_volumes||[]).length} removed${(result.failed_volumes||[]).length?` · ${result.failed_volumes.length} failed`:''} · ${result.protected_volumes||0} rollback-protected`);else if(kind==='networks')notify(`Network cleanup complete · ${(result.removed_networks||[]).length} removed${(result.failed_networks||[]).length?` · ${result.failed_networks.length} failed`:''} · ${result.protected_networks||0} rollback-protected`);else notify(`Build cache cleanup complete · ${fmtBytes(Number(result.reclaimed_bytes||0))} reclaimed`);await loadOneHostOverview(h);if(kind==='images'&&details?.host.id===h.id){try{const data=await api<HostOverview>(`/api/hosts/${h.id}/overview?include_images=1`);setDetails({host:h,data})}catch{}}if(kind==='volumes'&&volumeDetails?.host.id===h.id){try{const data=await api<VolumeSummary[]>(`/api/hosts/${h.id}/volumes`);setVolumeDetails({host:h,data:Array.isArray(data)?data:[]})}catch{}}if(kind==='networks'&&networkDetails?.host.id===h.id){try{const data=await api<NetworkSummary[]>(`/api/hosts/${h.id}/networks`);setNetworkDetails({host:h,data:Array.isArray(data)?data:[]})}catch{}}}else notify(`${kind==='build-cache'?'Build cache':kind[0].toUpperCase()+kind.slice(1)} cleanup ${job.status}: ${job.error||'unknown error'}`);clearCleanupLater(key);cleanupMonitorInFlight.current.delete(jobID);return}}catch(e:any){setCleanupOps(v=>({...v,[key]:{job_id:jobID,status:'failed',percent:100,stage:'Status check failed',error:e.message}}));notify(e.message);clearCleanupLater(key);cleanupMonitorInFlight.current.delete(jobID);return}await new Promise(r=>window.setTimeout(r,650))}setCleanupOps(v=>({...v,[key]:{job_id:jobID,status:'failed',percent:100,stage:'Cleanup status timed out',error:'Timed out waiting for cleanup job'}}));notify(`${h.name}: timed out waiting for cleanup status`);clearCleanupLater(key);cleanupMonitorInFlight.current.delete(jobID)}
 const submitCleanup=async(h:Host,kind:'images'|'volumes'|'networks'|'build-cache',url:string)=>{const key=cleanupKey(h,kind);setCleanupOps(v=>({...v,[key]:{job_id:0,status:'queued',percent:2,stage:'Submitting cleanup'}}));try{const x:any=await api(`${url}${url.includes('?')?'&':'?'}async=1`,{method:'POST'}),id=Number(x.job_id||0);if(!id)throw new Error('Cleanup did not return a job id');setCleanupOps(v=>({...v,[key]:{job_id:id,status:'queued',percent:3,stage:'Cleanup queued'}}));void monitorCleanup(h,kind,id)}catch(e:any){setCleanupOps(v=>{const n={...v};delete n[key];return n});notify(e.message)}}
 const openImages=async(h:Host)=>{setDetailsBusy(true);try{const data=await api<HostOverview>(`/api/hosts/${h.id}/overview?include_images=1`);setDetails({host:h,data})}catch(e:any){notify(e.message)}finally{setDetailsBusy(false)}}
 const prune=async(h:Host,current?:HostOverview)=>{const d=current||hostOverview[h.id];const eligible=Number(d?.images_cleanup_eligible??d?.images_unused??0),protectedCount=Number(d?.images_rollback_protected||0);if(!d||!eligible||cleanupState(h,'images'))return;const msg=`Delete ${eligible} cleanup-eligible unused image${eligible===1?'':'s'} on ${h.name}?\n\n${protectedCount?`${protectedCount} unused image${protectedCount===1?' is':'s are'} protected by retained rollback snapshots and will be kept.\n\n`:''}Docker will also keep images referenced by existing containers.`;if(!confirm(msg))return;await submitCleanup(h,'images',`/api/hosts/${h.id}/images/prune`)}
 const openVolumes=async(h:Host)=>{setVolumeBusy(true);try{const x:any=await api(`/api/hosts/${h.id}/volumes`),data:VolumeSummary[]=Array.isArray(x)?x:[];setHostVolumes(v=>({...v,[h.id]:data}));setHostInventoryErrors(v=>({...v,[h.id]:{...(v[h.id]||{}),volumes:undefined}}));setVolumeDetails({host:h,data})}catch(e:any){setHostInventoryErrors(v=>({...v,[h.id]:{...(v[h.id]||{}),volumes:e.message||'Volume inventory unavailable'}}));notify(e.message)}finally{setVolumeBusy(false)}}
 const pruneAnonymousVolumes=async(h:Host)=>{if(cleanupState(h,'volumes'))return;const vols=volumeDetails?.host.id===h.id?volumeDetails.data:await api<VolumeSummary[]>(`/api/hosts/${h.id}/volumes`);const count=vols.filter(v=>v.unused&&v.anonymous&&!v.rollback_protected).length,protectedCount=vols.filter(v=>v.unused&&v.anonymous&&v.rollback_protected).length;if(!count)return;if(!confirm(`Delete ${count} cleanup-eligible anonymous Docker volume${count===1?'':'s'} on ${h.name}?\n\nNamed volumes, bind mounts${protectedCount?' and '+protectedCount+' rollback-protected anonymous volume'+(protectedCount===1?'':'s'):''} are kept.`))return;await submitCleanup(h,'volumes',`/api/hosts/${h.id}/volumes/prune-anonymous`)}
 const deleteNamedVolume=async(h:Host,v:VolumeSummary)=>{if(v.usage_known===false||!!v.inspect_error||!v.unused||v.anonymous||v.rollback_protected)return;if(!confirm(`Delete unused named volume “${v.name}” on ${h.name}?\n\nThis may contain persistent application data. Vibewatch will refuse deletion if any container or retained rollback snapshot still references it.`))return;setVolumeAction(v.name);try{await api(`/api/hosts/${h.id}/volumes/named?name=${encodeURIComponent(v.name)}`,{method:'DELETE'});notify(`Named volume deleted · ${v.name}`);await openVolumes(h);await loadHostOverview()}catch(e:any){notify(e.message)}finally{setVolumeAction('')}}
