 const pruneNetworks=async(h:Host)=>{if(cleanupState(h,'networks'))return;const data=networkDetails?.host.id===h.id?networkDetails.data:await api<NetworkSummary[]>(`/api/hosts/${h.id}/networks`);const eligible=data.filter(n=>n.unused&&!n.system&&!n.rollback_protected).length,protectedCount=data.filter(n=>n.rollback_protected&&!n.in_use).length;if(!eligible)return;if(!confirm(`Delete ${eligible} unused custom Docker network${eligible===1?'':'s'} on ${h.name}?\n\nDocker default networks, networks in use${protectedCount?' and rollback-protected networks':''} are kept.`))return;await submitCleanup(h,'networks',`/api/hosts/${h.id}/networks/prune`)}
