   <div><div className="mb-1 flex items-center justify-between text-[11px] text-zinc-500"><span>Docker image space reclaimable</span><span>{fmtPct(reclaimPct)}</span></div><div className="wt-reclaim-track h-1.5 overflow-hidden rounded-full"><div className="wt-reclaim-fill h-full rounded-full transition-all" style={{width:`${reclaimPct}%`}}/></div></div>
