   setVerificationSaving(true)
   await api(`/api/hosts/${container.policy.host_id}/verification?container=${encodeURIComponent(container.name)}`,{method:'PUT',body:JSON.stringify(profile)})
   setVerificationSaving(false)
   const runningState:VerificationState={...verificationModal.state,host_id:container.policy.host_id,container_name:container.name,scope_type:profile.scope_type,scope_key:profile.scope_key,status:'running',checked_at:new Date().toISOString(),error:''}
   setVerificationModal(v=>v&&opKey(v.container)===opKey(container)?{...v,state:runningState}:v)
   patchVerification?.(container.policy.host_id,container.name,runningState)
   const result=await api<VerificationResult>(`/api/hosts/${container.policy.host_id}/verification?container=${encodeURIComponent(container.name)}`,{method:'POST'})
   const [x,hist]=await Promise.all([api<any>(`/api/hosts/${container.policy.host_id}/verification?container=${encodeURIComponent(container.name)}`),api<VerificationHistoryEntry[]>(`/api/verification-history?host_id=${container.policy.host_id}&container=${encodeURIComponent(container.name)}&limit=10`).catch(()=>[])])
