 const waitJob=async(rp:RestorePoint,id:number)=>{for(let i=0;i<1200;i++){try{const x:any=await api(`/api/job-status/${id}`);const job:Job=x.job,progress=x.progress||{},percent=Number(progress.percent||0),stage=String(progress.stage||job.status||'Working');setRunning(v=>({...v,[rp.id]:{job_id:id,percent,stage}}));setLiveOperation(v=>{if(!v||v.kind!=='rollback'||v.target!==rp.container_name||(v.job_id>0&&v.job_id!==id))return v;const genericTerminal=job.status==='failed'&&/^(rollback|operation) failed$/i.test(stage.trim());return{...v,job_id:id,status:job.status,percent,stage,error:job.error||undefined,failed_at_percent:genericTerminal?v.percent:undefined,failed_stage:genericTerminal?v.stage:undefined}});if(job.status==='success'||job.status==='failed'||job.status==='cancelled'||job.status==='skipped'){setRunning(v=>{const n={...v};delete n[rp.id];return n});await load();notify(job.status==='success'?`${rp.container_name}: rollback completed`:`${rp.container_name}: rollback failed · ${job.error||'unknown error'}`);return}}catch(e:any){setRunning(v=>{const n={...v};delete n[rp.id];return n});setLiveOperation(v=>v&&v.kind==='rollback'&&v.target===rp.container_name?{...v,status:'failed',error:e.message,failed_at_percent:v.percent,failed_stage:v.stage}:v);notify(e.message);return}await new Promise(r=>window.setTimeout(r,650))}setRunning(v=>{const n={...v};delete n[rp.id];return n});setLiveOperation(v=>v&&v.kind==='rollback'&&v.target===rp.container_name?{...v,status:'failed',error:'Timed out waiting for rollback',failed_at_percent:v.percent,failed_stage:v.stage}:v);notify(`${rp.container_name}: timed out waiting for rollback`)}
