 const ready=points.filter(canRollback).length,fullApplication=points.filter(p=>p.writable_layer&&p.volume_data_protected&&(p.status==='ready'||p.status==='restored')).length,fullContainer=points.filter(p=>p.writable_layer&&!p.volume_data_protected&&(p.status==='ready'||p.status==='restored')).length,degraded=points.filter(p=>p.status==='degraded'||p.integrity_status==='degraded').length
 const recoveryArchiveBytes=points.reduce((n,p)=>n+Number(p.archive_bytes||0),0),recoveryImageBytes=points.reduce((n,p)=>n+Number(p.restore_image_bytes||0),0),recoveryFootprintBytes=points.reduce((n,p)=>n+Number(p.footprint_bytes||0),0),recoveryFootprintEstimated=points.some(p=>!!p.footprint_estimated)
