 const unitId=(u:BackupUnit)=>`${u.host_id}:${u.kind}:${u.key}`
 const create=async(u:BackupUnit)=>{setCreating(unitId(u));try{await api('/api/container-backups/snapshot',{method:'POST',body:JSON.stringify({host_id:u.host_id,kind:u.kind,key:u.key})});notify(`Config snapshot created · ${u.name}`);await load()}catch(e:any){notify(e.message)}finally{setCreating('')}}
 const deleteArchived=async(u:BackupUnit)=>{if(u.live)return;const count=(u.snapshots||[]).length;if(!confirm(`Delete archived config “${u.name}” and its ${count} retained snapshot${count===1?'':'s'}?\n\nLinked restore points will expire and their rollback-object protection will be released. This cannot be undone.`))return;setDeleting(unitId(u));try{const x:any=await api(`/api/container-backups/archived?host_id=${u.host_id}&kind=${encodeURIComponent(u.kind)}&key=${encodeURIComponent(u.key)}`,{method:'DELETE'});notify(`Archived config deleted · ${u.name} · ${x.removed_snapshots||0} snapshot${Number(x.removed_snapshots||0)===1?'':'s'}`);await load()}catch(e:any){notify(e.message)}finally{setDeleting('')}}
 const createAll=async()=>{const targets=units.filter(u=>u.live);if(!targets.length)return;if(!confirm(`Create one configuration snapshot for all ${targets.length} live stacks/services?\n\nSnapshots are created sequentially. Retention remains ${retention} per stack/service.`))return;setBulk({active:true,current:0,total:targets.length,name:'Preparing…',success:0,failed:0});let success=0,failed=0;for(let i=0;i<targets.length;i++){const u=targets[i];setBulk({active:true,current:i,total:targets.length,name:`${u.host_name} · ${u.name}`,success,failed});try{await api('/api/container-backups/snapshot',{method:'POST',body:JSON.stringify({host_id:u.host_id,kind:u.kind,key:u.key})});success++}catch{failed++}setBulk({active:true,current:i+1,total:targets.length,name:`${u.host_name} · ${u.name}`,success,failed})}await load();setBulk({active:false,current:targets.length,total:targets.length,name:'Completed',success,failed});notify(`Config snapshot run complete · ${success} created${failed?` · ${failed} failed`:''}`)}
 const dl=(u:BackupUnit,s:BackupSnapshot,format:'zip'|'compose')=>`/api/container-backups/download?host_id=${u.host_id}&kind=${encodeURIComponent(u.kind)}&key=${encodeURIComponent(u.key)}&snapshot=${encodeURIComponent(s.id)}&format=${format}`
 const filtered=units.filter(u=>{const name=`${u.name} ${u.key}`.toLowerCase(),containers=(u.containers||[]).join(' ').toLowerCase();if(nameFilter&& !name.includes(nameFilter.toLowerCase()))return false;if(hostFilter&&u.host_id!==hostFilter)return false;if(typeFilter&&u.kind!==typeFilter)return false;if(containerFilter&&!containers.includes(containerFilter.toLowerCase()))return false;if(stateFilter==='live'&&!u.live)return false;if(stateFilter==='archived'&&u.live)return false;const count=(u.snapshots||[]).length;if(snapshotFilter==='with'&&count===0)return false;if(snapshotFilter==='without'&&count>0)return false;return true})
