 useEffect(()=>{load();const t=window.setInterval(load,8000);return()=>window.clearInterval(t)},[])
 const reset=()=>{setEditId(0);setName('');setHostID(0);setAutomationID(0);setScopeType('stack');setScopeKey('');setPolicyMode('manual');setAllowPreflightWarnings(false);setStopOnFailure(true);setRollbackCompleted(false);setSteps([])}
 const edit=(c:UpdateChain)=>{setChainTab('chains');setSelectedChainId(c.id);setEditorOpen(true);setEditId(c.id);setName(c.name);setHostID(c.host_id);setAutomationID(c.automation_id||0);setScopeType(c.scope_type==='stack'?'stack':'custom');setScopeKey(c.scope_key||'');setPolicyMode(['manual','auto','ignore'].includes(c.policy_mode)?c.policy_mode as 'manual'|'auto'|'ignore':'manual');setAllowPreflightWarnings(!!c.allow_preflight_warnings);setStopOnFailure(!!c.stop_on_failure);setRollbackCompleted(!!c.rollback_completed);setSteps((c.steps||[]).map((x,i)=>({...x,position:i+1,current_action:x.current_action||'skip'})));window.scrollTo({top:0,behavior:'smooth'})}
 const syncStack=(stack=scopeKey)=>{if(!hostID||!stack){setSteps([]);return}const members=stackMembers(stack),old=new Map<string,UpdateChainStep>(steps.map(x=>[x.container_name,x]));setSteps(members.map((c,i)=>({position:i+1,container_name:c.name,current_action:old.get(c.name)?.current_action||'skip',wait_seconds:old.get(c.name)?.wait_seconds||0})));if(!members.length)notify('No live containers were found for this stack.')}
