 const save=async()=>{setSaving(true);try{const savedHostID=hostID;await api('/api/update-chains',{method:'POST',body:JSON.stringify({id:editId||0,name,host_id:hostID,automation_id:automationID,scope_type:scopeType,scope_key:scopeType==='stack'?scopeKey:'',policy_mode:policyMode,allow_preflight_warnings:policyMode==='auto'?allowPreflightWarnings:false,stop_on_failure:stopOnFailure,rollback_completed:rollbackCompleted,steps:steps.map((s,i)=>({...s,position:i+1}))})});notify(editId?'Update chain saved':'Update chain created');setEditorOpen(false);reset();await load();const h=hosts.find((x:Host)=>x.id===savedHostID);if(h&&reloadHost)await reloadHost(h,true)}catch(e:any){notify(e.message)}finally{setSaving(false)}}
 const del=async(c:UpdateChain)=>{if(!confirm(`Delete update chain ${c.name}?\n\nThe chain configuration is removed. Existing run history remains available.`))return;try{await api(`/api/update-chains/${c.id}`,{method:'DELETE'});if(editId===c.id){reset();setEditorOpen(false)}if(selectedChainId===c.id)setSelectedChainId(0);setChainReview(null);await load();const h=hosts.find((x:Host)=>x.id===c.host_id);if(h&&reloadHost)await reloadHost(h,true);notify('Update chain deleted')}catch(e:any){notify(e.message)}}
 const previewRun=async(c:UpdateChain)=>{setChainReview({chain:c,loading:true});try{const plan=await api<ChainPreflightPlan>(`/api/update-chains/${c.id}/preflight`,{method:'POST'});setChainReview({chain:c,loading:false,plan})}catch(e:any){setChainReview({chain:c,loading:false,error:e.message||'Chain Preflight failed'})}}
 const run=async(c:UpdateChain)=>{setRunning(c.id);try{const x:any=await api(`/api/update-chains/${c.id}/run`,{method:'POST'});setChainReview(null);notify(`${c.name} queued · job #${x.job_id}`);await load()}catch(e:any){notify(e.message)}finally{setRunning(0)}}
 const addStep=()=>{const used=new Set(steps.map(s=>s.container_name));const next=containers.find(c=>!used.has(c.name));if(!next){notify(hostID?'No additional container is available on this host.':'Select a host first.');return}setSteps(v=>[...v,{position:v.length+1,container_name:next.name,current_action:'skip',wait_seconds:0}])}
