 const statusLabel=(s:string)=>s==='blocked'||s==='blocked_preflight'?'Held':s==='skipped_preflight'?'Skipped':s==='no_changes'?'No changes':s==='skipped_current'?'Current':s==='skipped_snoozed'?'Snoozed':s==='recovery_required'?'Recovery required':s==='recovered'?'Recovered':s==='interrupted'?'Interrupted':s==='rolled_back'?'Rolled back':s||'Never run'
