  <div className="v2-history-cards-concept">{filtered.map(h=><details key={h.id} className="v2-history-card-concept"><summary><span className={`v2-history-icon-concept ${h.action==='rollback'?'tone-rose':h.status==='failed'?'tone-peach':'tone-mint'}`}><Icon name={h.action==='rollback'?'rollback':h.status==='failed'?'shield-alert':'check'}/></span><span><strong>{h.action==='rollback'?`${h.container_name} rolled back`:h.status==='failed'?`${h.container_name} update failed`:`${h.container_name} updated successfully`}</strong><p>{h.from_version||'Unknown'} → {h.to_version||'Unknown'} · {hn(h.host_id)}</p><small>{fmt(h.ts)} · {h.trigger||'system'}{h.actor?` · ${h.actor}`:''}</small></span><span className={`v2-status-pill ${h.action==='rollback'?'danger':h.status==='success'?'success':h.status==='failed'?'danger':'warning'}`}>{h.action==='rollback'?'Rolled back':h.status}</span></summary><div className="v2-history-detail-concept"><div><span>Preflight</span><b>{h.preflight_status?preflightLabel(h.preflight_status):'—'}</b></div><div><span>Verification</span><b>{h.verification_status?verificationLabel(h.verification_status):'—'}</b></div><div><span>Duration</span><b>{h.duration_ms?`${(h.duration_ms/1000).toFixed(1)}s`:'—'}</b></div><div><span>Dependencies</span><b>{h.dependency_count?`${h.dependency_count} · ${h.dependency_status||'detected'}`:'None recorded'}</b></div>{h.error?<div className="v2-history-detail-wide"><span>Error</span><p>{h.error}</p></div>:null}{h.preflight_details?<HistoryDetailBlock raw={h.preflight_details} kind="preflight"/>:null}{h.verification_details?<HistoryDetailBlock raw={h.verification_details} kind="verification"/>:null}</div></details>)}{filtered.length===0?<Empty text="No update history matches the active filters."/>:null}</div>
