  <Card className="v2-concept-table-card !p-0"><div className="v2-concept-table-head v2-job-concept-grid"><span>Job</span><span>Target</span><span>Started</span><span>Progress</span><span>Status</span><span></span></div><div className="v2-concept-table-body">{filtered.map(j=>{const tx=transactions[j.id],progress=j.status==='success'?100:j.status==='failed'||j.status==='cancelled'?100:j.status==='running'?Math.max(12,Number((tx as any)?.percent||48)):0;return <button type="button" key={j.id} className="v2-concept-table-row v2-job-concept-grid" onClick={()=>openJob(j)}><span className="v2-entity-cell"><b>{j.type}</b><small>Job #{j.id} · {j.trigger}</small></span><span>{j.container_name||'—'}<small className="v2-row-note">{hn(j.host_id)}</small></span><span>{j.started_at?fmt(j.started_at):'Waiting'}</span><span><div className="v2-mini-progress"><i style={{width:`${progress}%`}}/></div>{tx&&['running','queued'].includes(j.status)?<small className="v2-row-note">{txLabel(tx.state)}</small>:null}</span><span className={`v2-status-pill ${j.status==='success'?'success':j.status==='failed'?'danger':j.status==='running'?'info':j.status==='queued'?'warning':'neutral'}`}>{j.status}</span>{j.status==='queued'?<span onClick={e=>e.stopPropagation()}><Button kind="danger" disabled={cancelling===j.id} onClick={(e:any)=>cancel(j,e)}>{cancelling===j.id?'…':'Cancel'}</Button></span>:<Icon name="more"/>}</button>})}{filtered.length===0?<Empty text="No jobs match the active filters."/>:null}</div></Card>
