function parseAppLog(line:string){try{const x:any=JSON.parse(line);const {time,level,msg,...context}=x;return{time:time||'',level:String(level||'INFO').toUpperCase(),message:msg||line,context}}catch{return{time:'',level:'INFO',message:line,context:{}}}}
